{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "In rats, the N-methyl tropane ester [18F]MCL-322 showed high brain uptake (3.23% ID/g in striatum at 5 min), directly demonstrating efficient BBB passage of a tropane ester closely related to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "In cynomolgus monkeys, [11C]β-CIT, a N-methyl tropane ester, reached 5.5% of injected radioactivity in brain, indicating high CNS access despite a basic ionizable tropane nitrogen.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "In humans, the tropane radioligand 18F-AZAN rapidly entered the brain, showing that tropane-based basic amines can achieve meaningful CNS exposure in the most translationally relevant species.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "In rats, granisetron, a tropane-like basic amide, showed increasing unbound brain/blood ratios by microdialysis, confirming that ionizable bicyclic amines can penetrate the BBB and access brain tissue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "N-methylpiperidinyl acetates were detected in mouse brain within 1 min after IV injection, supporting ready BBB passage of small N-methyl azabicyclic/piperidine esters like the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a tropane-based N-methyl ester with very high structural and pharmacological similarity to multiple radiotracers and drugs that show rapid, high brain uptake across rats, monkeys, baboons, and humans. The strong transferable experimental evidence overrides the physicochemical prior of low passive permeability due to ionization.",
  "evidence_gaps": [
    "No direct experimental brain or plasma exposure data are available for the exact query molecule.",
    "The effect of the primary hydroxyl and full ionization at physiological pH on passive permeability is not directly measured.",
    "Efflux transporter liability for the query is inferred but not experimentally confirmed.",
    "Metabolic stability of the ester moiety after systemic administration is unknown."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C04", "C15", "C08", "C13", "C12"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "tropane/azabicyclic esters"
    }
  ],
  "revision_action": "initial"
}

